/**
 * A shopping cart for a customer on a Wix eCommerce site.
 *
 * A cart holds the customer's selected items, applied discounts (coupons, automatic rules),
 * delivery information, and payment details before the order is placed.
 *
 * Carts may be deleted after a period of inactivity.
 *
 * Use the [Cart Service](https://dev.wix.com/docs/api-reference/business-solutions/e-commerce/purchase-flow/cart-v2/introduction) to manage carts by ID,
 * or the [Current Cart Service](https://dev.wix.com/docs/api-reference/business-solutions/e-commerce/purchase-flow/cart-v2/introduction) to manage
 * the current customer's cart by session.
 */
export interface Cart {
  /**
   * Cart ID.
   * @format GUID
   * @readonly
   */
  _id?: string;
  /**
   * Date and time the Cart was created.
   * @readonly
   */
  _createdDate?: Date | null;
  /**
   * Date and time the Cart was last updated.
   * @readonly
   */
  _updatedDate?: Date | null;
  /**
   * Revision number, which increments by 1 each time the Cart is updated.
   * @readonly
   */
  revision?: string;
  /**
   * Line items added to the Cart by the customer.
   * This list may include in-stock items and invalid or out-of-stock items.
   * @maxSize 300
   * @readonly
   */
  lineItems?: V2LineItem[];
  /**
   * The sum of all line item final prices.
   * @readonly
   */
  subtotal?: ConvertedMoney;
  /**
   * Optional message left by the customer.
   * Usually intended for the merchant and contains special instructions, requests, or clarifications related to the order.
   * @maxLength 1000
   */
  note?: string | null;
  /**
   * List of coupons added to the Cart.
   * Currently only one coupon code is supported.
   * @maxSize 1
   * @readonly
   */
  coupons?: V2Coupon[];
  /** Information about the source of the Cart, detailing the origin or context in which the Cart was created. */
  source?: CartSource;
  /** Information about the site from which the Cart's line items were added. */
  businessInfo?: BusinessInfo;
  /** Information about the customer that owns the Cart. */
  customerInfo?: CustomerInfo;
  /** Delivery-related information associated with the Cart. */
  deliveryInfo?: DeliveryInfo;
  /** Tax-related information associated with the Cart. */
  taxInfo?: TaxInfo;
  /** Payment-related information associated with the Cart. */
  paymentInfo?: PaymentInfo;
  /**
   * Whether the Cart has been placed as an Order.
   * Defaults to `false`.
   * @readonly
   */
  orderPlaced?: boolean;
  /**
   * Order ID.
   * Empty until the checkout process is completed.
   * @format GUID
   * @readonly
   */
  orderId?: string | null;
  /**
   * Persistent ID that correlates the Cart with the created Order after checkout is completed.
   * @format GUID
   * @readonly
   */
  purchaseFlowId?: string | null;
  /**
   * Additional cart settings.
   *
   * Settings can only be configured at cart creation time and can't be changed afterwards.
   * @immutable
   * @readonly
   */
  settings?: CartSettings;
  /**
   * Custom checkout URL to redirect the customer to a checkout page.
   * By default, customers are redirected to the standard Wix checkout page.
   * Clients can override this behavior by providing their own URL here.
   * If the URL contains the placeholder `{checkout_id}`, it will be replaced with the actual Cart ID.
   * @maxLength 2048
   */
  customCheckoutUrl?: string | null;
  /**
   * Custom fields.
   * [Extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields) must be configured in the app dashboard before they can be accessed with API calls.
   */
  extendedFields?: ExtendedFields;
  /**
   * Whether this is the customer's current cart.
   * The current cart can be accessed using the identity context (for example, `visitorId` from session cookies) without an explicit cart ID.
   * @readonly
   */
  currentCart?: boolean;
  /**
   * Legacy fields for backward compatibility with Cart V1.
   * Should be used only by the Cart API proxy to populate V1 fields.
   * Used to avoid re-calculating these fields in the proxy.
   * @internal
   */
  legacyFields?: LegacyFields;
  /**
   * Forms associated with the Cart's line items.
   * @internal
   * @readonly
   * @maxSize 1000
   */
  forms?: FormInfo[];
  /**
   * Whether this is a demo cart.
   * Demo carts are created in the Wix editor for merchant preview and can't proceed to checkout.
   *
   * Default: `false`
   */
  demo?: boolean;
  /**
   * Indicators that help clients decide whether to call EstimateCart.
   * @internal
   * @readonly
   */
  estimationIndicators?: CartEstimationIndicators;
  /**
   * Applied discounts from totals calculator. Used internally for re-calculation without discounts, and by cart-v1-proxy.
   * @internal
   * @readonly
   * @maxSize 100
   */
  tcAppliedDiscounts?: AppliedDiscount[];
}

export interface V2LineItem {
  /**
   * Unique identifier for the line item within the cart.
   * @format GUID
   */
  _id?: string;
  /** Display name for the line item. */
  name?: TranslatableString;
  /** Quantity details for the line item. */
  quantityInfo?: ItemQuantityInfo;
  /** Pricing details for the line item. */
  pricing?: ItemPricingInfo;
  /** Information about the line item's origin. */
  source?: ItemSource;
  /** Display details for the item. */
  attributes?: ItemAttributes;
  /** Delivery configuration for the line item. */
  deliveryConfig?: ItemDeliveryConfig;
  /** Tax configuration for the line item. */
  taxConfig?: ItemTaxConfig;
  /** Payment configuration for the line item. */
  paymentConfig?: ItemPaymentConfig;
  /** Inventory availability status for the line item. */
  status?: ItemStatusWithLiterals;
  /**
   * Custom extended fields for the line item object.
   *
   * [Extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields) must be configured using the Checkout & Orders - Line Items Schema Plugin in the app dashboard before they can be accessed with API calls.
   */
  extendedFields?: ExtendedFields;
  /**
   * Additional fees added to this item's calculation.
   * @internal
   * @maxSize 5
   */
  additionalFees?: V1AdditionalFee[];
  /**
   * Modifier groups added to the item.
   * @maxSize 25
   */
  modifierGroups?: ModifierGroup[];
  /**
   * Discounts applied to this line item.
   * @maxSize 100
   */
  discounts?: ItemDiscount[];
  /**
   * Whether the line item is a custom line item.
   * Custom line items don't trigger the Catalog service plugin.
   */
  customLineItem?: boolean;
  /**
   * Coupon scopes: which app and items a coupon applies to.
   * Internal to Wix; used by Bookings, Stores, and Events with the [Coupons API](https://bo.wix.com/wix-docs/rest/stores/coupons/valid-scope-values).
   * @internal
   * @maxSize 100
   */
  couponScopes?: Scope[];
}

export interface TranslatableString {
  /**
   * __Required.__ String in the site's default language as defined in the [request envelope](https://dev.wix.com/docs/build-apps/develop-your-app/frameworks/self-hosting/supported-extensions/backend-extensions/add-self-hosted-service-plugin-extensions#request-envelope).
   *
   * Min: 1 character.
   * Max: 200 characters.
   * @minLength 1
   * @maxLength 200
   */
  original?: string;
  /**
   * String translated into the buyer's language.
   *
   * Min: 1 character.
   * Max: 400 characters.
   * Default: Same as `original`.
   * @minLength 1
   * @maxLength 400
   */
  translated?: string | null;
}

export interface ItemQuantityInfo {
  /**
   * Confirmed quantity to purchase.
   * The minimum of `requestedQuantity` and `availableQuantity`.
   * @min 1
   * @max 100000
   */
  confirmedQuantity?: number;
  /**
   * Quantity the customer originally requested.
   * @min 1
   * @max 100000
   */
  requestedQuantity?: number;
  /** Maximum quantity available for purchase. */
  availableQuantity?: number | null;
  /**
   * Whether the line item quantity is fixed and can't be changed.
   *
   * Default: `false`
   */
  fixedQuantity?: boolean;
}

export interface ItemPricingInfo {
  /**
   * Final unit price after discounts.
   * Includes tax when `taxInfo.pricesIncludeTax` is true.
   */
  unitPrice?: ConvertedMoney;
  /**
   * Final total price for this item (unit price × quantity).
   * Includes tax when `taxInfo.pricesIncludeTax` is true.
   */
  totalPrice?: ConvertedMoney;
  /**
   * Additional price description.
   * For example, when the price is `0` but you need more detail, such as "Starts at $67".
   */
  priceDescription?: PriceDescription;
  /** Whether the price isn't yet defined and will be updated after the order is created. */
  priceUndetermined?: boolean;
  /** Detailed breakdown of price components. */
  breakdown?: ItemPriceBreakdown;
}

export interface ConvertedMoney {
  /**
   * Monetary amount in the original currency, as specified in `businessInfo.currencyCode`.
   * @format DECIMAL_VALUE
   * @decimalValue options { gte:0, lte:999999999, maxScale:3 }
   */
  amount?: string;
  /**
   * Monetary amount in the converted currency, as specified in `customerInfo.currencyCode`.
   *
   * Default: `amount`.
   * @format DECIMAL_VALUE
   * @decimalValue options { gte:0, lte:999999999, maxScale:3 }
   * @readonly
   */
  convertedAmount?: string;
}

export interface PriceDescription {
  /**
   * __Required.__ Price description in the site's default language as defined in the [request envelope](https://dev.wix.com/docs/build-apps/develop-your-app/frameworks/self-hosting/supported-extensions/backend-extensions/add-self-hosted-service-plugin-extensions#request-envelope).
   * @minLength 1
   * @maxLength 100
   */
  original?: string;
  /**
   * Price description translated into the buyer's language.
   *
   * Default: Same as `original`.
   * @minLength 1
   * @maxLength 100
   */
  translated?: string | null;
}

export interface ItemPriceBreakdown {
  /**
   * Full catalog price for a single item before discounts, including modifiers.
   * Includes tax when `taxInfo.pricesIncludeTax` is true.
   */
  fullPrice?: ConvertedMoney;
  /**
   * Catalog sale price for a single item, including modifiers.
   * Includes tax when `taxInfo.pricesIncludeTax` is true.
   */
  salePrice?: ConvertedMoney;
  /**
   * Total price of all modifiers for a single item.
   * Includes tax when `taxInfo.pricesIncludeTax` is true.
   */
  totalModifiersPrice?: ConvertedMoney;
  /**
   * Full catalog price for a single item without modifiers.
   * Used by Cart & Checkout V1 API proxies when converting to legacy entities.
   * @internal
   * @decimalValue options { gte:0, lte:1000000000000000, maxScale:3 }
   */
  fullPriceBeforeModifiers?: string | null;
  /**
   * Catalog sale price for a single item without modifiers.
   * Stored in the site currency.
   * Used by Cart & Checkout V1 API proxies when converting to legacy entities.
   * @internal
   * @decimalValue options { gte:0, lte:1000000000000000, maxScale:3 }
   */
  salePriceBeforeModifiers?: string | null;
}

export interface ItemSource {
  /**
   * Catalog and item reference: IDs for the item and catalog, plus optional details.
   * Optional for custom line items, which don't trigger the Catalog service plugin.
   */
  catalogReference?: CatalogReference;
  /** Overriding values for catalog item properties. */
  catalogOverrideFields?: CatalogOverrideFields;
  /**
   * When `catalogReference.catalogItemId` isn't the actual catalog item ID, this field returns the true catalog item ID.
   * For example, for Wix Bookings, `catalogReference.catalogItemId` is the booking ID, so this value is the service ID.
   * In most cases, this matches `catalogReference.catalogItemId`.
   * Used in membership validation.
   * @minLength 1
   * @maxLength 36
   */
  rootCatalogItemId?: string | null;
  /**
   * ID of the app managing the inventory.
   * @format GUID
   */
  inventoryAppId?: string | null;
  /**
   * ID of the app providing upsells for this item.
   * @internal
   * @format GUID
   */
  upsellOptionsAppId?: string | null;
  /**
   * Line-item ID in external systems.
   * @internal
   * @minLength 1
   * @maxLength 100
   */
  externalResourceId?: string | null;
}

/** Used for grouping line items. Sent when an item is added to a cart, checkout, or order. */
export interface CatalogReference {
  /**
   * ID of the item within the catalog it belongs to.
   * @minLength 1
   * @maxLength 36
   */
  catalogItemId?: string;
  /**
   * ID of the app providing the catalog.
   *
   * You can get your app's ID from its page in the [app dashboard](https://dev.wix.com/dc3/my-apps/).
   *
   * For items from Wix catalogs, the following values always apply:
   * + Wix Stores: `"215238eb-22a5-4c36-9e7b-e7c08025e04e"`
   * + Wix Bookings: `"13d21c63-b5ec-5912-8397-c3a5ddb27a97"`
   * + Wix Restaurants: `"9a5d83fd-8570-482e-81ab-cfa88942ee60"`
   * @minLength 1
   */
  appId?: string;
  /**
   * Additional item details in `key:value` pairs.
   *
   * Use this optional field for more specificity with item selection. The values of the `options` field differ depending on which catalog is providing the items.
   *
   * For Wix Stores products, learn more about integrating with [Catalog V3](https://dev.wix.com/docs/api-reference/business-solutions/stores/catalog-v3/e-commerce-integration)
   * or [Catalog V1](https://dev.wix.com/docs/api-reference/business-solutions/stores/catalog-v1/catalog/e-commerce-integration), depending on [the version the site uses](https://dev.wix.com/docs/api-reference/business-solutions/stores/catalog-versioning/introduction).
   */
  options?: Record<string, any> | null;
}

export interface CatalogOverrideFields {
  /** Display name for the line item. */
  name?: TranslatableString;
  /**
   * Sale price for a single item after modifiers, before discounts.
   * @decimalValue options { gte:0, lte:999999999, maxScale:3 }
   */
  salePrice?: string | null;
  /**
   * Full price for a single item after modifiers, before discounts.
   * @decimalValue options { gte:0, lte:999999999, maxScale:3 }
   */
  fullPrice?: string | null;
  /**
   * Description lines for the item.
   * Shown when displaying the line item to buyers.
   * @maxSize 20
   */
  descriptionLines?: DescriptionLine[];
  /** Physical properties of the item. */
  physicalProperties?: PhysicalProperties;
  /** Item image. */
  image?: string;
  /** Selected payment option for the item. */
  paymentOption?: PaymentOption;
  /**
   * Partial payment due upfront during checkout.
   * Only when `paymentOption.value` is `DEPOSIT_ONLINE`.
   * @format DECIMAL_VALUE
   * @decimalValue options { gt:0, lte:999999999, maxScale:3 }
   */
  depositAmount?: string | null;
  /**
   * Whether to save the payment method on the order.
   *
   * Default: `false`
   */
  savePaymentMethod?: boolean | null;
  /**
   * ID of the app managing inventory.
   * @format GUID
   */
  inventoryAppId?: string | null;
  /**
   * Whether the line item quantity is fixed and can't be changed.
   * When not set, falls back to the value from the catalog.
   * @internal
   */
  fixedQuantity?: boolean | null;
}

